def fit_fill(I):
    from collections import defaultdict
    H,W=len(I),len(I[0])
    rows=defaultdict(list)
    for r in range(3,H):
        for c in range(3,W):
            if I[r][c]!=0: rows[r].append((c,I[r][c]))
    r0=max(rows,key=lambda r:len(rows[r]))
    c0=rows[r0][0][0]
    P={}
    for c,v in rows[r0]: P[(c-c0)%7]=v
    assert len(P)==7
    offs={}
    for r in rows:
        cand=None
        for d in range(7):
            if all(P.get((c-(c0+d))%7)==v for c,v in rows[r]): cand=d; break
        offs[r]=cand
    return P,offs,r0,c0
