def transform(g):
    H,W=len(g),len(g[0])
    last=g[H-1][3:]
    L=next(cand for cand in range(1,10) if all(last[i]==last[i%cand] for i in range(len(last))))
    C=last[:L]; idx={v:i for i,v in enumerate(C)}
    o=[row[:] for row in g]
    for r in range(H):
        for c in range(W):
            if g[r][c]==0:
                if r<2 or c<2: o[r][c]=1
                elif r==2 or c==2: o[r][c]=4
    es={}
    for r in range(3,H):
        cnt=Counter()
        for c in range(3,W):
            if g[r][c] in idx: cnt[(idx[g[r][c]]-(c-3))%L]+=1
        if cnt:
            tot=sum(cnt.values()); best,n=cnt.most_common(1)[0]
            es[r]=best if n>=tot-1 else None
    rs=sorted(r for r in es if es[r] is not None)
    steps=Counter((es[rs[i+1]]-es[rs[i]])%L for i in range(len(rs)-1) if rs[i+1]==rs[i]+1)
    step=steps.most_common(1)[0][0] if steps else 1
    for r in range(3,H):
        if es.get(r) is None:
            lo=max([x for x in rs if x<r],default=None); hi=min([x for x in rs if x>r],default=None)
            es[r]=(es[lo]+(r-lo)*step)%L if lo is not None else (es[hi]-(hi-r)*step)%L
    for r in range(3,H):
        for c in range(3,W):
            if g[r][c]==0: o[r][c]=C[(c-3+es[r])%L]
    return o
